verify_receipt_trigger_semantics() {
  local database="$1"
  local label="$2"
  local trigger_spec trigger_name expected_prefix normalized_sql
  local -a required_receipt_trigger_semantics

  IFS=',' read -r -a required_receipt_trigger_semantics <<< "$REQUIRED_RECEIPT_TRIGGER_SEMANTICS"
  for trigger_spec in "${required_receipt_trigger_semantics[@]}"; do
    trigger_name="${trigger_spec%%=*}"
    expected_prefix="${trigger_spec#*=}"
    normalized_sql="$(sqlite3 "$database" "SELECT lower(replace(replace(replace(replace(sql, char(10), ''), char(13), ''), char(9), ''), ' ', '')) FROM sqlite_master WHERE type='trigger' AND name='$trigger_name';")"
    if [[ "$normalized_sql" != *"$expected_prefix"* || "$normalized_sql" != *"$RECEIPT_IMMUTABILITY_ABORT"* ]]; then
      echo "error: $label does not enforce immutable receipt trigger semantics: $trigger_name" >&2
      return 1
    fi
  done

  local -a required_measurement_trigger_semantics
  IFS=',' read -r -a required_measurement_trigger_semantics <<< "$REQUIRED_MEASUREMENT_TRIGGER_SEMANTICS"
  for trigger_spec in "${required_measurement_trigger_semantics[@]}"; do
    trigger_name="${trigger_spec%%=*}"
    expected_prefix="${trigger_spec#*=}"
    normalized_sql="$(sqlite3 "$database" "SELECT lower(replace(replace(replace(replace(sql, char(10), ''), char(13), ''), char(9), ''), ' ', '')) FROM sqlite_master WHERE type='trigger' AND name='$trigger_name';")"
    if [[ "$normalized_sql" != *"$expected_prefix"* || "$normalized_sql" != *"$MEASUREMENT_IMMUTABILITY_ABORT"* ]]; then
      echo "error: $label does not enforce immutable measurement-delta trigger semantics: $trigger_name" >&2
      return 1
    fi
  done
}

verify_approval_trigger_semantics() {
  local database="$1"
  local label="$2"
  local trigger_spec trigger_name expected_prefix expected_abort normalized_sql serialized_semantics
  local -a required_approval_trigger_semantics

  serialized_semantics="${REQUIRED_APPROVAL_TRIGGER_SEMANTICS//),/);}"
  IFS=';' read -r -a required_approval_trigger_semantics < <(printf '%s\n' "$serialized_semantics")
  if (( ${#required_approval_trigger_semantics[@]} != 20 )); then
    echo "error: $label approval-ledger trigger contract is internally inconsistent" >&2
    return 1
  fi
  for trigger_spec in "${required_approval_trigger_semantics[@]}"; do
    IFS='|' read -r trigger_name expected_prefix expected_abort <<< "$trigger_spec"
    if [[ -z "$trigger_name" || -z "$expected_prefix" || -z "$expected_abort" ]] || \
        ! normalized_sql="$(sqlite3 "$database" "SELECT lower(replace(replace(replace(replace(sql, char(10), ''), char(13), ''), char(9), ''), ' ', '')) FROM sqlite_master WHERE type='trigger' AND name='$trigger_name';")"; then
      echo "error: $label approval-ledger trigger contract is malformed: $trigger_name" >&2
      return 1
    fi
    if [[ "$normalized_sql" != *"$expected_prefix"* || "$normalized_sql" != *"$expected_abort"* ]]; then
      echo "error: $label does not enforce immutable approval-ledger trigger semantics: $trigger_name" >&2
      return 1
    fi
  done
}

verify_object_semantics() {
  local database="$1"
  local label="$2"
  local object_type="$3"
  local serialized_semantics="$4"
  local expected_count="$5"
  local contract_label="$6"
  local semantic_spec object_name normalized_sql expected_fragment part_index
  local -a semantic_specs semantic_parts

  IFS=';' read -r -a semantic_specs < <(printf '%s\n' "$serialized_semantics")
  if (( ${#semantic_specs[@]} != expected_count )); then
    echo "error: $label $contract_label contract is internally inconsistent" >&2
    return 1
  fi
  for semantic_spec in "${semantic_specs[@]}"; do
    IFS='|' read -r -a semantic_parts < <(printf '%s\n' "$semantic_spec")
    object_name="${semantic_parts[0]:-}"
    if [[ -z "$object_name" ]] || (( ${#semantic_parts[@]} < 2 )) || \
        ! normalized_sql="$(sqlite3 "$database" "SELECT lower(replace(replace(replace(replace(sql, char(10), ''), char(13), ''), char(9), ''), ' ', '')) FROM sqlite_master WHERE type='$object_type' AND name='$object_name';")"; then
      echo "error: $label $contract_label contract is malformed: $object_name" >&2
      return 1
    fi
    normalized_sql="${normalized_sql//ifnotexists/}"
    for ((part_index = 1; part_index < ${#semantic_parts[@]}; part_index++)); do
      expected_fragment="${semantic_parts[$part_index]}"
      if [[ -z "$expected_fragment" || "$normalized_sql" != *"$expected_fragment"* ]]; then
        echo "error: $label does not enforce $contract_label semantics: $object_name" >&2
        return 1
      fi
    done
  done
}

verify_measurement_index_semantics() {
  verify_object_semantics "$1" "$2" index \
    "$REQUIRED_MEASUREMENT_INDEX_SEMANTICS" "$REQUIRED_MEASUREMENT_INDEX_SEMANTIC_COUNT" \
    "measurement evidence index"
}

