    "$REQUIRED_NATIVE_MEASUREMENT_TABLE_SEMANTICS" "$REQUIRED_NATIVE_MEASUREMENT_TABLE_SEMANTIC_COUNT" \
    "native measurement table" &&
    verify_object_semantics "$1" "$2" index \
      "$REQUIRED_NATIVE_MEASUREMENT_INDEX_SEMANTICS" "$REQUIRED_NATIVE_MEASUREMENT_INDEX_SEMANTIC_COUNT" \
